        "SELECT name, email, phone, street_address, total_spend FROM users"
    ).fetchall()
    table = "\n".join(",".join(str(c) for c in r) for r in rows)
    return llm.chat.completions.create(model=MODEL, max_tokens=800, messages=[
        {"role": "system", "content": SEGMENT_PROMPT},
        {"role": "user", "content": table},
    ]).choices[0].message.content

