@app.post("/upload")
async def upload(file: UploadFile, user=Depends(current_user)):
    if file.content_type not in {"text/plain", "application/pdf"} or file.size > 5_000_000:
        raise HTTPException(400, "unsupported file")
    text = sanitize_text(extract_text(await file.read(), file.content_type))
    chunks = splitter.split_text(text)
    coll = chroma.get_or_create_collection(f"user_{user.id}")
    meta = {"source": "user_upload", "filename": file.filename, "uploader": user.id}
    coll.add(documents=chunks, ids=[str(uuid4()) for _ in chunks], metadatas=[meta] * len(chunks))
    return {"chunks": len(chunks)}

